-- Seed data: the 10 topics, their prerequisite edges, and 2 demo users. Nothing else.
-- ON CONFLICT DO NOTHING makes this safe to re-run on every startup against persistent Postgres.

-- Topic ids ARE the fixed learning order and the HLR one-hot index (id - 1). Never renumber.
INSERT INTO topics (id, name, slug) VALUES
    (1,  'Arrays',         'arrays'),
    (2,  'Strings',        'strings'),
    (3,  'Two Pointers',   'two-pointers'),
    (4,  'Sliding Window', 'sliding-window'),
    (5,  'HashMap',        'hashmap'),
    (6,  'LinkedList',     'linkedlist'),
    (7,  'Stack',          'stack'),
    (8,  'Trees',          'trees'),
    (9,  'Graphs',         'graphs'),
    (10, 'DP',             'dp')
ON CONFLICT DO NOTHING;

-- (topic_id, prerequisite_id): "to study topic_id, first be solid on prerequisite_id".
-- Approved graph; see docs/CONTRACT.md section 2. Arrays -> LinkedList is deliberately absent.
INSERT INTO topic_prerequisites (topic_id, prerequisite_id) VALUES
    (3,  1),   -- Arrays       -> Two Pointers
    (4,  3),   -- Two Pointers -> Sliding Window
    (4,  2),   -- Strings      -> Sliding Window
    (5,  1),   -- Arrays       -> HashMap
    (5,  2),   -- Strings      -> HashMap
    (7,  1),   -- Arrays       -> Stack
    (7,  2),   -- Strings      -> Stack
    (8,  6),   -- LinkedList   -> Trees
    (8,  7),   -- Stack        -> Trees
    (9,  8),   -- Trees        -> Graphs
    (9,  5),   -- HashMap      -> Graphs
    (10, 5),   -- HashMap      -> DP
    (10, 8)    -- Trees        -> DP
ON CONFLICT DO NOTHING;

-- Demo users for the user switcher (no real login). History for Alex is added in a later phase.
INSERT INTO users (display_name) VALUES
    ('Alex'),
    ('Sam')
ON CONFLICT DO NOTHING;
-- GENERATED by tools/gen_problems.py. Do not edit by hand: change the generator and re-run it.
-- Idempotent: the app runs this on every startup, so each INSERT skips rows that already exist
-- (problems by slug, tests by (problem_id, ordinal)). Requires the topics rows from data.sql.

-- ===== 1. Maximum Subarray Sum (topic 1, MEDIUM) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      starter_code, time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 1, 'Maximum Subarray Sum', 'max-subarray-sum', 'MEDIUM',
'You are given an array of integers that may contain negative numbers. Choose a contiguous, **non-empty** block of elements so that their total is as large as possible, and print that total.

A block of one element is allowed, so the answer is never smaller than the largest element.

**Constraints:** 1 <= n <= 200000, -10^4 <= nums[i] <= 10^4. The answer may not fit in a 32-bit int.',
'Line 1: n
Line 2: n space-separated integers',
'A single integer: the largest possible block sum',
'import java.io.*;
import java.util.*;

public class Main {
    // Return the largest sum of any non-empty contiguous subarray of nums.
    static long solve(int[] nums) {
        // TODO: write your algorithm here
        return 0;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        int n = nextInt(in);
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) nums[i] = nextInt(in);
        System.out.println(solve(nums));
    }

    static int nextInt(StreamTokenizer in) throws IOException {
        in.nextToken();
        return (int) in.nval;
    }
}
',
2000, 500, 1500
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'max-subarray-sum');

