-- ===== 12. Valid Parentheses (topic 7, EASY) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      starter_code, time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 7, 'Valid Parentheses', 'valid-parentheses', 'EASY',
'The string contains only the bracket characters `( ) [ ] { }`. It is balanced when every opening bracket is closed by the **same type** of bracket, and brackets close in the reverse order they were opened. The empty string is balanced. Decide whether the string is balanced.

**Constraints:** 0 <= |s| <= 400000.',
'Line 1: s (may be empty)',
'true or false',
'import java.io.*;
import java.util.*;

public class Main {
    // Return true if every bracket is closed by the same type in the right order.
    static boolean solve(String s) {
        // TODO: write your algorithm here
        return false;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        // An empty line can arrive as null at end of input; treat it as an empty string.
        if (s == null) s = "";
        System.out.println(solve(s));
    }
}
',
2000, 500, 600
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'valid-parentheses');

-- SAMPLE #1: valid nesting
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 1, '({}[])
', 'true
', NULL
FROM problems p WHERE p.slug = 'valid-parentheses'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

-- SAMPLE #2: crossed pairs
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 2, '[(])
', 'false
', NULL
FROM problems p WHERE p.slug = 'valid-parentheses'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 2);

-- EDGE #3: empty string: catches treating empty input as invalid
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 3, '
', 'true
', NULL
FROM problems p WHERE p.slug = 'valid-parentheses'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 3);

-- EDGE #4: a lone closer: catches popping from an empty stack
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 4, ')
', 'false
', NULL
FROM problems p WHERE p.slug = 'valid-parentheses'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 4);

-- BOUNDARY #5: opener left at the end: catches not checking the stack is empty
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 5, '(()
', 'false
', NULL
FROM problems p WHERE p.slug = 'valid-parentheses'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 5);

-- BOUNDARY #6: final closer has the wrong type: catches counting brackets instead of matching
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 6, '([{}]}
', 'false
', NULL
FROM problems p WHERE p.slug = 'valid-parentheses'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 6);

-- LARGE #7: 190000 nested pairs: repeatedly deleting () [] {} is O(n^2) and times out
